import json
import re
from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo

# Node params arrive in the `params` dict (sandbox-bootstrap.py), not as variables.
piece_id = params["piece_id"]
mode = params["mode"]
markdown = params.get("markdown")
variants = params.get("variants")
draft_version = params.get("draft_version")

PIECES = "social_content_pieces"
TYPES = {
    "social_post": {"label": "Social media post", "folder": "Social media posts"},
    "article": {"label": "Article", "folder": "Articles"},
    "email": {"label": "Email", "folder": "Emails"},
    "announcement": {"label": "Announcement", "folder": "Announcements"},
    "visual": {"label": "Visual", "folder": "Visuals"},
}
# Defaults from the product spec (inputs/marketing-agent-spec.html, "Content defaults") and the MVP document.
RULES = {
    "social_post": {
        "channels": {
            "instagram": {"words": [80, 150], "max_chars": 2200, "structure": "hook, value, CTA", "tone": "friendly, visual, upbeat", "hashtags": [3, 5], "emoji_max": 3, "link": "say 'link in bio', no URL in the caption", "image": "square 1080 + story 1080x1920"},
            "facebook": {"words": [40, 80], "max_chars": 2000, "structure": "hook, value, CTA", "tone": "conversational, local, community", "hashtags": [0, 2], "emoji_max": 2, "link": "link in the caption", "image": "square 1080"},
            "linkedin": {"words": [150, 250], "max_chars": 3000, "structure": "hook, insight, takeaway, CTA", "tone": "professional, insightful, first person", "hashtags": [0, 2], "emoji_max": 1, "link": "link in the caption", "image": "banner 1200x628"},
            "google_business": {"words": [50, 100], "max_chars": 1500, "structure": "update or offer, CTA", "tone": "plain, factual, offer-led", "hashtags": [0, 0], "emoji_max": 0, "link": "button link", "image": "square 1080"},
        },
        "default_channels": ["instagram", "facebook", "linkedin"],
    },
    "article": {"words": [600, 1000], "tone": "helpful expert, plain English, Year 8 reading level", "structure": "title, intro under 80 words, 3 to 5 H2 sections, conclusion, CTA", "seo": "1 focus keyword, meta description up to 155 characters, URL slug", "extras": "3 short social teasers promoting the article", "image": "1 header image, banner 1200x628"},
    "email": {"single": {"words": [80, 200], "tone": "personal, direct, one clear ask", "structure": "greeting, message, 1 CTA, sign-off"}, "newsletter": {"words": [250, 500], "tone": "warm, informative, light", "structure": "intro, 2 to 3 sections, CTA, sign-off"}, "subject_max_chars": 50, "preview_max_chars": 90, "footer": "business name, contact details and an unsubscribe link (mandatory)"},
    "announcement": {"single": {"words": [80, 200], "tone": "personal, direct, one clear ask", "structure": "greeting, message, 1 CTA, sign-off"}, "newsletter": {"words": [250, 500], "tone": "warm, informative, light", "structure": "intro, 2 to 3 sections, CTA, sign-off"}, "subject_max_chars": 50, "preview_max_chars": 90, "footer": "business name, contact details and an unsubscribe link (mandatory)"},
    "visual": {"headline_max_words": 8, "subhead_max_words": 15, "total_max_words": 30, "tone": "bold, punchy, scannable at a glance", "sizes": "A4 portrait (print), square 1080, story 1080x1920, banner 1200x628", "required": "logo, headline, CTA, website or phone", "optional": "QR code to the CTA link, offer badge, date", "note": "Draft the copy and layout notes only; images are produced later."},
    "global": {"language": "Australian English (colour, organise, centre)", "no_em_dashes": True, "dates": "dd/mm/yyyy", "missing_facts": "[[MISSING: what is needed]]", "testimonials": "never, not even real ones", "cta": "every piece has exactly one; from the brief, else the Brand Kit default", "absolute_claims": "avoid best, cheapest, guaranteed, number one unless the Brand Kit allows them"},
}
ABSOLUTE = ["best", "cheapest", "guaranteed", "guarantee", "number one", "#1", "no.1", "unbeatable", "world-class", "lowest price"]


def text(value):
    if value is None:
        return ""
    if isinstance(value, (list, tuple)):
        return ", ".join(str(v) for v in value)
    return str(value).strip()


def as_list(value):
    if isinstance(value, list):
        return [str(v).strip() for v in value if str(v).strip()]
    return [part.strip() for part in text(value).replace(",", "\n").splitlines() if part.strip()]


def add_business_days(day, count):
    step = 1 if count >= 0 else -1
    remaining = abs(count)
    while remaining > 0:
        day = day + timedelta(days=step)
        if day.weekday() < 5:
            remaining -= 1
    return day


def find_job_item(title):
    """The job's own WorkQ item: the one bound to this process run (its title is the process title, not the piece's)."""
    run_id = text(dict(trigger).get("runId"))
    if not run_id:
        return None
    for todo in api.workq.list(search="Draft a content piece") or []:
        if text(todo.get("processRunId")) == run_id:
            return todo
    return None


settings = api.extension.settings() or {}
folder = text(settings.get("knowledge_folder")) or "Social posts"
zone = ZoneInfo(text(settings.get("time_zone")) or "Australia/Sydney")
try:
    lead = int(settings.get("review_lead_days") or 2)
except (TypeError, ValueError):
    lead = 2

found = api.records.get(type_slug=PIECES, record_id=piece_id)
row = (found or {}).get("record") or {}
missing = not row
if missing and mode != "context":
    raise RuntimeError("The content piece was not found. It may have been deleted or archived.")
data = row.get("data") or {}
piece_title = text(row.get("title") or data.get("piece_title"))
content_type = text(data.get("content_type"))
type_info = TYPES.get(content_type, {"label": content_type or "Content", "folder": "Other"})

# Every mode assigns every output.
ready = False
problem = ""
brand = {}
piece = {}
rules = {}
publish_date = ""
publish_at = ""
review_date = ""
type_label = type_info["label"]
due_date_set = False
flags = []
check_summary = ""
knowledge_path = ""
version = int(data.get("current_version") or 0)

if mode == "context":
    try:
        brand = json.loads(api.files.read(file=f"{folder}/Brand Kit/brand-kit.json"))
    except Exception:
        brand = {}
    if missing:
        problem = "This content piece was not found. It may have been deleted or archived."
    elif not brand.get("company_name"):
        problem = "There is no confirmed Brand Kit yet. Create one under Records > Brand Kits and confirm it, then start this content piece again."
    elif content_type not in TYPES:
        problem = "Choose a content type for this piece (social media post, article, email, announcement or visual), then start it again."
    else:
        ready = True
    today = datetime.now(zone).date()
    chosen = text(data.get("publish_date"))[:10]
    try:
        publish = date.fromisoformat(chosen) if chosen else None
    except ValueError:
        publish = None
    if publish is None or publish < today:
        publish = add_business_days(today, lead + 1)
    review = add_business_days(publish, -lead)
    if review < today:
        review = today
    publish_date = publish.isoformat()
    review_date = review.isoformat()
    publish_at = datetime(publish.year, publish.month, publish.day, 8, 0, tzinfo=zone).isoformat()
    channels = as_list(data.get("channels"))
    if content_type == "social_post" and not channels:
        channels = RULES["social_post"]["default_channels"]
    piece = {
        "title": piece_title,
        "content_type": content_type,
        "type_label": type_label,
        "channels": channels,
        "topic": text(data.get("topic")),
        "angle": text(data.get("angle")),
        "brief": text(data.get("brief")),
        "cta": text(data.get("cta")) or text(brand.get("default_cta")) or text(settings.get("default_cta")),
        "cta_url": text(data.get("cta_url")) or text(brand.get("default_cta_url")),
        "publish_date": publish.strftime("%d/%m/%Y"),
        "sequence": text(data.get("sequence")),
        "origin": text(data.get("origin")) or "adhoc",
    }
    rules = {"type": RULES.get(content_type, {}), "global": RULES["global"]}
    if ready:
        api.records.update(type_slug=PIECES, record_id=piece_id, record={"data": {"publish_date": publish_date, "review_date": review_date}})
        item = find_job_item(piece_title)
        if item:
            api.workq.update(todo_id=item["id"], due_date=publish_date)
            due_date_set = True

elif mode == "check":
    try:
        brand = json.loads(api.files.read(file=f"{folder}/Brand Kit/brand-kit.json"))
    except Exception:
        brand = {}
    body = text(markdown)
    low = body.lower()
    for word in as_list(brand.get("words_to_avoid")):
        if word.lower() in low:
            flags.append(f"FAIL: uses '{word}', which is on the Brand Kit's words to avoid.")
    for claim in as_list(brand.get("claims_not_allowed")):
        if claim.lower() in low:
            flags.append(f"FAIL: makes the claim '{claim}', which the Brand Kit does not allow.")
    for disclaimer in as_list(brand.get("mandatory_disclaimers")):
        if disclaimer.lower() not in low:
            flags.append(f"FAIL: the mandatory disclaimer '{disclaimer}' is missing.")
    if "[[missing" in low:
        flags.append("FAIL: has [[MISSING]] placeholders to fill in before it can be used.")
    if "—" in body:
        flags.append("FAIL: contains em dashes; the house style has none.")
    if re.search(r"\b(testimonial|review from|said our customer)\b", low) or re.search(r"[“\"][^”\"]{12,}[”\"]\s*[–-]\s*[A-Z]", body):
        flags.append("FAIL: looks like it includes a testimonial or customer quote; those are never used.")
    for term in ABSOLUTE:
        if re.search(r"(?<![a-z])" + re.escape(term) + r"(?![a-z])", low):
            flags.append(f"WARN: absolute claim '{term}'; check it is allowed and true.")
    if content_type in ("email", "announcement"):
        if "unsubscribe" not in low:
            flags.append("FAIL: email footer has no unsubscribe link.")
        if not text(brand.get("sender_address")):
            flags.append("FAIL: no sender name and address in the Brand Kit for the email footer.")
    for variant in variants or []:
        if not isinstance(variant, dict):
            continue
        channel = text(variant.get("channel"))
        copy = text(variant.get("copy") or variant.get("caption") or variant.get("body"))
        limits = RULES.get("social_post", {}).get("channels", {}).get(channel) if content_type == "social_post" else None
        words = len(copy.split())
        if limits:
            low_w, high_w = limits["words"]
            if words and not (low_w <= words <= high_w):
                flags.append(f"WARN: {channel} copy is {words} words (aim for {low_w} to {high_w}).")
            tags = len(re.findall(r"(?<!\w)#\w+", copy)) + len(variant.get("hashtags") or [])
            low_h, high_h = limits["hashtags"]
            if not (low_h <= tags <= high_h):
                flags.append(f"WARN: {channel} has {tags} hashtags (aim for {low_h} to {high_h}).")
        if not text(variant.get("cta")) and "cta" not in low and not copy:
            flags.append(f"WARN: {channel or 'a variant'} has no call to action.")
    fails = len([f for f in flags if f.startswith("FAIL")])
    warns = len(flags) - fails
    check_summary = "All brand and compliance checks passed." if not flags else f"{fails} to fix, {warns} to check:\n" + "\n".join(flags)
    item = find_job_item(piece_title)
    if item:
        api.workq.comment(todo_id=item["id"], body="**Brand and compliance checks** (assistive, not legal advice)\n\n" + ("All passed." if not flags else "\n".join(f"- {f}" for f in flags)))
    api.records.update(type_slug=PIECES, record_id=piece_id, record={"data": {"check_summary": (f"{fails} to fix, {warns} to check" if flags else "All passed")}})

elif mode == "file":
    import docx

    version = int(draft_version or 1)
    when = text(data.get("publish_date"))[:10]
    try:
        stamp = date.fromisoformat(when).strftime("%d-%m-%Y")
    except ValueError:
        stamp = datetime.now(zone).strftime("%d-%m-%Y")
    slug = re.sub(r"[^a-z0-9]+", "-", piece_title.lower()).strip("-")[:40] or "piece"
    base = f"{folder}/{type_info['folder']}/{stamp}_{slug}_v{version}"
    body = text(markdown)
    api.files.put(file=f"{base}.md", content=body)
    document = docx.Document()
    for line in body.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        heading = re.match(r"^(#{1,4})\s+(.*)$", stripped)
        if heading:
            document.add_heading(heading.group(2), level=min(len(heading.group(1)), 4))
        elif stripped.startswith(("- ", "* ")):
            document.add_paragraph(stripped[2:], style="List Bullet")
        else:
            document.add_paragraph(stripped.replace("**", ""))
    scratch = api.files.scratch_path(f"{slug}_v{version}.docx")
    document.save(scratch)
    api.files.put(file=f"{base}.docx", scratch_file=scratch)
    knowledge_path = f"{base}.docx"
    api.records.update(type_slug=PIECES, record_id=piece_id, record={"data": {"knowledge_path": knowledge_path, "current_version": version}})

elif mode in ("posted", "skipped"):
    # The Stage column is the record's pipeline stage. Automations cannot move a stage yet (the records bridge has
    # create/update/upsert only, and an update refuses `piece_stage`), so these steps record nothing for now.
    pass

else:
    raise RuntimeError(f"Unknown mode '{mode}'.")
